    "ingredients": "[\n  {\n    \"name\": \"Copper Tripeptide-1\",\n    \"description\": \"Мощный пептид, который стимулирует синтез коллагена и способствует заживлению и обновлению кожи.\"\n  },\n  {\n    \"name\": \"Acetyl Hexapeptide-8\",\n    \"description\": \"Пептид, подобный ботоксу, который помогает расслабить лицевые мышцы и уменьшить мимические морщины.\"\n  },\n  {\n    \"name\": \"Palmitoyl Hexapeptide-12\",\n    \"description\": \"Продвинутый пептид, который помогает улучшить упругость и эластичность кожи.\"\n  },\n  {\n    \"name\": \"Гиалуроновая кислота\",\n    \"description\": \"Глубоко увлажняющий ингредиент, который наполняет кожу и уменьшает появление тонких линий.\"\n  },\n  {\n    \"name\": \"Церамид\",\n    \"description\": \"Незаменимый липид, который помогает укрепить кожный барьер и поддерживать баланс увлажнения.\"\n  },\n  {\n    \"name\": \"Сквалан\",\n    \"description\": \"Природный смягчающий агент, который обеспечивает глубокую гидратацию и помогает улучшить текстуру кожи.\"\n  }\n]",
