    "ingredients": "[\n  {\n    \"name\": \"Комплекс центеллы азиатской\",\n    \"description\": \"Мощный заживляющий комплекс с азиатикозидом, мадекассовой кислотой и азиатиковой кислотой для восстановления кожи.\"\n  },\n  {\n    \"name\": \"sh-Polypeptide-7\",\n    \"description\": \"Продвинутый пептид, который способствует регенерации кожи и процессам заживления.\"\n  },\n  {\n    \"name\": \"Дикалия глицирризинат\",\n    \"description\": \"Экстракт корня солодки, который обеспечивает противовоспалительные и успокаивающие преимущества.\"\n  },\n  {\n    \"name\": \"Пантенол\",\n    \"description\": \"Витамин B5, который помогает успокоить раздраженную кожу и способствует заживлению.\"\n  },\n  {\n    \"name\": \"Экстракты растительных культур каллуса\",\n    \"description\": \"Экстракты культур каллуса Vitis Vinifera и Rosa Damascena для улучшенных заживляющих свойств.\"\n  },\n  {\n    \"name\": \"Шлемник байкальский\",\n    \"description\": \"Экстракт корня китайского шлемника с противовоспалительными и антиоксидантными свойствами.\"\n  }\n]",
