    "ingredients": "[\n  {\n    \"name\": \"Copper Tripeptide-1\",\n    \"description\": \"Медный пептид, стимулирующий синтез коллагена и поддерживающий прочность волос и здоровье фолликулов.\"\n  },\n  {\n    \"name\": \"Sophora Japonica Extract\",\n    \"description\": \"Антиоксидантный растительный экстракт, помогающий защитить среду кожи головы.\"\n  },\n  {\n    \"name\": \"Salicylic Acid\",\n    \"description\": \"Кератолитик для кожи головы (0,25%), помогающий сохранять фолликулы свободными от отложений.\"\n  },\n  {\n    \"name\": \"Menthol\",\n    \"description\": \"Освежающий охлаждающий компонент (0,30%), успокаивающий кожу головы.\"\n  },\n  {\n    \"name\": \"Caffeine\",\n    \"description\": \"Известный стимулятор кожи головы, поддерживающий среду закрепления волос.\"\n  },\n  {\n    \"name\": \"Centella Asiatica + Scutellaria Baicalensis + Licorice Root\",\n    \"description\": \"Успокаивающее растительное трио, смягчающее и улучшающее состояние кожи головы.\"\n  },\n  {\n    \"name\": \"Allantoin\",\n    \"description\": \"Смягчающий компонент, сохраняющий спокойствие кожи головы при ежедневном использовании.\"\n  }\n]",
    "howToUse": "[\n  {\n    \"step\": \"Подготовка\",\n    \"instruction\": \"Тщательно очистите кожу головы с помощью HR³ MATRIX SCALP PEELING\"\n  },\n  {\n    \"step\": \"Нанесение\",\n    \"instruction\": \"Равномерно нанесите тоник на кожу головы и корни волос\"\n  },\n  {\n    \"step\": \"Массаж\",\n    \"instruction\": \"Аккуратно помассируйте кожу головы в течение 2-3 минут для улучшения впитывания\"\n  },\n  {\n    \"step\": \"Усиление\",\n    \"instruction\": \"Используйте с GENOSYS STAMP (ROLLER) для более глубокого проникновения\"\n  },\n  {\n    \"step\": \"Частота использования\",\n    \"instruction\": \"Используйте 2-3 раза в неделю для оптимальных результатов\"\n  }\n]",
