    "ingredients": "[\n  {\n    \"name\": \"Комплекс 10 витаминов\",\n    \"description\": \"Производное витамина A (антиоксидант, антивозрастной), Витамины B1, B2, B3, B4, B5, B7, B9 (баланс масла и влаги, успокоение, поддержка барьера), Витамин C (антивозрастной, осветление, пигментация), Витамин E (антиоксидант, увлажнение, укрепление)\"\n  },\n  {\n    \"name\": \"Комплекс 8 трав\",\n    \"description\": \"Экстракт листьев зелёного чая, экстракт листьев розмарина, экстракт центеллы азиатской, экстракт гриба тремелла, экстракт цветков ромашки, экстракт корня горца, экстракт корня байкальского шлемника, экстракт корня солодки — противовоспалительное, успокаивающее, антиоксидантное, защита барьера и увлажнение\"\n  },\n  {\n    \"name\": \"Niacinamide 2%\",\n    \"description\": \"Самый концентрированный активный компонент формулы — витамин B3, осветляющий, выравнивающий тон и поддерживающий барьер кожи.\"\n  },\n  {\n    \"name\": \"Аденозин\",\n    \"description\": \"Улучшает морщины и укрепляет кожу, увеличивая синтез коллагена и стимулируя фибробласты. Противовоспалительный эффект.\"\n  },\n  {\n    \"name\": \"Эритритол\",\n    \"description\": \"Охлаждение кожи и притяжение влаги для освежающего ощущения.\"\n  },\n  {\n    \"name\": \"Экстракт гриба тремелла\",\n    \"description\": \"Растительная альтернатива гиалуроновой кислоте для длительного увлажнения.\"\n  }\n]",
